// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MergingPool} from "../src/MergingPool.sol";

contract InvMutTest is Test {
    MergingPool c;

    function setUp() public { c = new MergingPool(address(this), address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(uint256 newWinnersPerPeriodAmount) public {
        // winnersPerPeriod is consumed as an array-length bound elsewhere (pickWinner), so keep it sane,
        // but the domain stays wide; the extra +1 in the mutant differs for EVERY admissible value.
        uint256 amount = bound(newWinnersPerPeriodAmount, 0, 10_000);
        c.updateWinnersPerPeriod(amount);
        // General rule: setting winners per period to x makes the stored value exactly x.
        assertTrue(c.winnersPerPeriod() == amount);
    }
}

